  static string Full(string path){return Path.GetFullPath(path).TrimEnd('\\','/');}
  static bool Same(string a,string b){return !string.IsNullOrEmpty(a)&&!string.IsNullOrEmpty(b)&&string.Equals(Full(a),Full(b),StringComparison.OrdinalIgnoreCase);}
  static string Canonical(string id){return (id??"").TrimStart('\\');}
  static string Hash(byte[] bytes){if(bytes==null)return "absent";using(var sha=SHA256.Create())return BitConverter.ToString(sha.ComputeHash(bytes)).Replace("-","").ToLowerInvariant();}
  static string HashFile(string file,int maximum=PayloadLimit){LauncherMaintenance.NoReparse(file);if(!File.Exists(file))return "absent";using(var input=new FileStream(file,FileMode.Open,FileAccess.Read,FileShare.Read)){if(input.Length>maximum)throw new IOException("所选文件超出管理大小限制。");using(var sha=SHA256.Create())return BitConverter.ToString(sha.ComputeHash(input)).Replace("-","").ToLowerInvariant();}}
  static byte[] Read(string path,int maximum=2097152){LauncherMaintenance.NoReparse(path);if(!File.Exists(path))return null;using(var input=new FileStream(path,FileMode.Open,FileAccess.Read,FileShare.Read)){if(input.Length>maximum)throw new IOException("文件超出管理大小限制。");var bytes=new byte[(int)input.Length];int offset=0,n;while(offset<bytes.Length&&(n=input.Read(bytes,offset,bytes.Length-offset))>0)offset+=n;if(offset!=bytes.Length)throw new IOException("文件在读取期间改变。");return bytes;}}
  static string Text(byte[] bytes){return bytes==null?"":Utf8.GetString(bytes).TrimStart('\uFEFF');}
  static bool Opaque(string value){return value!=null&&System.Text.RegularExpressions.Regex.IsMatch(value,"^[a-f0-9]{32}$");}
  static string Managed(string id){switch(Canonical(id)){case "ZombieBuddy":return "buddy";case "Viewpoint":return "viewpoint";case "PZVoxelStudioViewpoint":return "models";case "ShootToThrillMultiplayer":return "shoot";case "LaoYuTranslationJava":return "chinese";case "OrangeShootPresentation":return "retired";}var addon=ViewpointAddons.All.FirstOrDefault(a=>a.Id==Canonical(id));return addon==null?"":addon.Key;}
  static string Value(Dictionary<string,string> info,string key){string value;return info.TryGetValue(key,out value)?value:"";}
  static int CompareVersion(string actual,string bound,bool prefix){if(!System.Text.RegularExpressions.Regex.IsMatch(actual??"","^[0-9]+(?:\\.[0-9]+)*$")||!System.Text.RegularExpressions.Regex.IsMatch(bound??"","^[0-9]+(?:\\.[0-9]+)*$"))throw new IOException("作者版本条件或当前版本无法核实。");var a=actual.Split('.').Select(int.Parse).ToArray();var b=bound.Split('.').Select(int.Parse).ToArray();for(int i=0;i<(prefix?b.Length:Math.Max(a.Length,b.Length));i++){int x=i<a.Length?a[i]:0,y=i<b.Length?b[i]:0;if(x!=y)return x.CompareTo(y);}return 0;}
  internal static void Versions(string actual,Dictionary<string,string> metadata,string min,string max,bool prefix){string low=Value(metadata,min),high=Value(metadata,max);if(low!=""&&CompareVersion(actual,low,false)<0||high!=""&&CompareVersion(actual,high,prefix)>0)throw new IOException("当前版本不在作者声明的兼容范围内。");}
  static void JarIdentity(Candidate candidate){ValidateJarIdentity(candidate.Selected,candidate.Row.packageName);}
  internal static void ValidateJarIdentity(string file,string packageName){using(var zip=ZipFile.OpenRead(file)){if(zip.Entries.Count>100000||!zip.Entries.Any(e=>e.FullName.StartsWith(packageName.Replace('.','/')+"/",StringComparison.Ordinal)&&e.FullName.EndsWith(".class",StringComparison.Ordinal)))throw new IOException("声明的 Java 包不在所选 JAR 内。");}}
  static bool PreloadMatches(Snapshot s,Candidate c){foreach(var entry in s.Preloads.Where(p=>Canonical(p.Key)==c.Row.modId)){var row=entry.Value as Dictionary<string,object>;object info,jar;if(row==null||!row.TryGetValue("infPath",out info)||!(info is string)||!row.TryGetValue("jarPath",out jar)||!(jar is string)||!c.InfoFiles.Any(p=>Same(p,(string)info))||!c.Payloads.Any(p=>Same(p,(string)jar)))return false;}return true;}
  static bool MetadataPreloadMatches(Snapshot s,Candidate c){try{foreach(var entry in s.Preloads){var row=entry.Value as Dictionary<string,object>;object info=null,jar=null;bool ownId=Canonical(entry.Key)==c.Row.modId;bool ownInfo=row!=null&&row.TryGetValue("infPath",out info)&&info is string&&c.InfoFiles.Any(p=>Same(p,(string)info));if(!ownId&&!ownInfo)continue;if(!ownId||!ownInfo||!row.TryGetValue("jarPath",out jar)||!(jar is string)||!Absolute((string)jar)||!Full((string)jar).StartsWith(c.Root+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))return false;LauncherMaintenance.NoReparse((string)jar);}return true;}catch{return false;}}
  string[] Dirs(string root,Snapshot s,Budget budget){scanCancel.ThrowIfCancellationRequested();try{LauncherMaintenance.NoReparse(root);if(!Directory.Exists(root))return new string[0];var result=Directory.EnumerateDirectories(root).Take(4097).ToArray();budget.directories+=result.Length;if(result.Length>4096||budget.directories>12288)throw new IOException("组件目录数量超过读取预算。");return result.Where(path=>{try{LauncherMaintenance.NoReparse(path);return true;}catch{s.Incomplete=true;s.Warnings.Add("已跳过联接或重解析目录。");return false;}}).ToArray();}catch(OperationCanceledException){throw;}catch(Exception ex){s.Incomplete=true;s.Warnings.Add(ex.Message);return new string[0];}}
  static bool LoadingField(string key){return new[]{"id","require","versionMin","versionMax","ZBVersionMin","ZBVersionMax"}.Contains(key,StringComparer.OrdinalIgnoreCase)||key.StartsWith("java",StringComparison.OrdinalIgnoreCase);}
  static Encoding InfoEncoding(byte[] bytes,out int bom){bom=0;if(bytes!=null&&bytes.Length>=3&&bytes[0]==239&&bytes[1]==187&&bytes[2]==191){bom=3;return Utf8;}if(bytes!=null&&bytes.Length>=2&&bytes[0]==255&&bytes[1]==254){bom=2;return new UnicodeEncoding(false,false,true);}if(bytes!=null&&bytes.Length>=2&&bytes[0]==254&&bytes[1]==255){bom=2;return new UnicodeEncoding(true,false,true);}return Utf8;}
  static string InfoText(byte[] bytes){if(bytes==null)return "";int bom;var encoding=InfoEncoding(bytes,out bom);return encoding.GetString(bytes,bom,bytes.Length-bom);}
  static bool JavaLine(string line){int at=line.IndexOf('=');if(at<=0)return false;string key=line.Substring(0,at).Trim();return System.Text.RegularExpressions.Regex.IsMatch(key,"^javaJarFile[0-9]*$",System.Text.RegularExpressions.RegexOptions.IgnoreCase)||key.Equals("javaPkgName",StringComparison.OrdinalIgnoreCase)||key.Equals("javaPreload",StringComparison.OrdinalIgnoreCase);}
  static byte[] SuppressInfo(byte[] bytes){if(bytes==null)return null;int bom;var encoding=InfoEncoding(bytes,out bom);string text=InfoText(bytes);var kept=new StringBuilder();int start=0;for(int i=0;i<text.Length;i++){if(text[i]!='\r'&&text[i]!='\n')continue;int end=i+1;if(text[i]=='\r'&&end<text.Length&&text[end]=='\n'){end++;i++;}string line=text.Substring(start,end-start);if(!JavaLine(line))kept.Append(line);start=end;}if(start<text.Length){string last=text.Substring(start);if(!JavaLine(last))kept.Append(last);}return bytes.Take(bom).Concat(encoding.GetBytes(kept.ToString())).ToArray();}
  static bool OwnedInfo(string root,string file){if(!Absolute(file)||!Path.GetFileName(file).Equals("mod.info",StringComparison.OrdinalIgnoreCase))return false;string parent=Path.GetDirectoryName(Full(file));if(Same(parent,root))return true;if(!Same(Path.GetDirectoryName(parent),root))return false;string name=Path.GetFileName(parent);Version version;return name.Equals("common",StringComparison.OrdinalIgnoreCase)||Version.TryParse(name.Contains(".")?name:name+".0",out version);}
  static bool SuppressionIntent(Receipt r){return r.operation=="disable"||r.operation=="block"||r.operation=="uninstall";}
  // A committed enable/metadata restore is a barrier; a later explicit block/uninstall starts a new intent.
  static Receipt[] EffectiveSuppressions(IEnumerable<Receipt> source){var records=source.ToArray();return records.Select((r,i)=>new{Receipt=r,Index=i}).Where(x=>!x.Receipt.restored&&SuppressionIntent(x.Receipt)&&!records.Skip(x.Index+1).Any(r=>Same(r.sourceRoot,x.Receipt.sourceRoot)&&(r.operation=="enable"||r.operation=="restore"&&r.entries.Any(e=>e.kind=="metadata")))).Select(x=>x.Receipt).ToArray();}
  void LoadSuppressions(Snapshot s,Budget budget){var records=EffectiveSuppressions(s.Store.receipts).ToList();try{byte[] pending=Read(pendingPath);if(pending!=null){var r=Json().Deserialize<Receipt>(Text(pending));if(r!=null&&Opaque(r.id)&&r.version==1&&r.entries!=null&&r.entries.Count<=20&&Absolute(r.sourceRoot))records.Add(r);}}catch{ /* Recovery reports an invalid pending record independently. */ }
   foreach(var r in records.Where(v=>!v.restored&&(v.operation=="disable"||v.operation=="block"||v.operation=="uninstall")&&v.entries.Any(e=>e.kind=="metadata"))){try{if(!Opaque(r.id)||!SaveProfiles.Id(r.modId)||!Absolute(r.sourceRoot))throw new IOException();var preserved=new Dictionary<string,byte[]>(StringComparer.OrdinalIgnoreCase);foreach(var entry in r.entries.Where(e=>e.kind=="metadata")){if(!OwnedInfo(r.sourceRoot,entry.target)||entry.before=="absent"||entry.after=="absent")throw new IOException();byte[] before=Read(Backup(r,entry.index,false),262144),after=Read(Backup(r,entry.index,true),262144);budget.Charge(before==null?0:before.Length);if(Hash(before)!=entry.before||Hash(after)!=entry.after||Hash(SuppressInfo(before))!=entry.after)throw new IOException();preserved[Full(entry.target)]=before;}foreach(var pair in preserved)s.InfoBefore[pair.Key]=pair.Value;s.Suppressions[Full(r.sourceRoot)]=r;}catch{s.Incomplete=true;s.Warnings.Add("一个 Java 元数据恢复备份无法核实，未开放修改。");}}
  }
  Dictionary<string,string> Info(string file,Snapshot s,Budget budget){scanCancel.ThrowIfCancellationRequested();file=Full(file);Dictionary<string,string> cached;if(s.InfoCache.TryGetValue(file,out cached))return cached;byte[] raw=Read(file,262144),bytes;budget.Charge(raw==null?0:raw.Length);s.InfoRaw[file]=raw;if(raw!=null){scanFiles++;if(progress!=null&&DateTime.UtcNow>=nextScanReport){progress(-1,"正在识别 Java 模组 · 已读取 "+scanFiles+" 个元数据文件");nextScanReport=DateTime.UtcNow.AddMilliseconds(200);}}scanCancel.ThrowIfCancellationRequested();s.Evidence.Add(file+"="+Hash(raw));if(!s.InfoBefore.TryGetValue(file,out bytes))bytes=raw;var result=new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase);foreach(string line in InfoText(bytes).Split(new[]{'\r','\n'})){int at=line.IndexOf('=');if(at<=0)continue;string key=line.Substring(0,at).Trim(),value=line.Substring(at+1).Trim();if(key.Equals("id",StringComparison.OrdinalIgnoreCase)&&Managed(value)!="")s.ProtectedInfo.Add(file);string prior;if(result.TryGetValue(key,out prior)){if(prior!=value&&LoadingField(key)){s.AmbiguousInfo.Add(file);if(key.Equals("require",StringComparison.OrdinalIgnoreCase))result[key]=prior+","+value;}continue;}result[key]=value;}s.InfoCache[file]=result;return result;}
  internal static string Payload(string root,string directory,string relative){if(string.IsNullOrWhiteSpace(relative)||Path.IsPathRooted(relative)||!relative.EndsWith(".jar",StringComparison.Ordinal)||relative.IndexOfAny(new[]{'\r','\n','\0',':'})>=0)throw new IOException("Java 文件声明不是安全的相对 JAR 路径。");string path=Full(Path.Combine(directory,relative));if(!path.StartsWith(Full(root)+Path.DirectorySeparatorChar,StringComparison.OrdinalIgnoreCase))throw new IOException("Java 文件声明超出所属模组目录。");LauncherMaintenance.NoReparse(path);if(("/"+path.Substring(Full(root).Length+1).Replace('\\','/')).IndexOf("/media/java/server/",StringComparison.OrdinalIgnoreCase)>=0)throw new IOException("服务端 Java 模组不由本机客户端管理。");return path;}
  void Add(string root,string source,string item,Snapshot s,Budget budget,HashSet<string> seen){
   scanCancel.ThrowIfCancellationRequested();root=Full(root);if(!seen.Add(root))return;try{LauncherMaintenance.NoReparse(root);if(!Directory.Exists(root))return;var dirs=Dirs(root,s,budget);string common=dirs.FirstOrDefault(d=>Path.GetFileName(d).Equals("common",StringComparison.OrdinalIgnoreCase));string active=null;
    foreach(string directory in dirs){Version version;string name=Path.GetFileName(directory);if(!Version.TryParse(name.Contains(".")?name:name+".0",out version)||version.Major!=s.Version.Major||version>s.Version)continue;if(active==null||version>Version.Parse(Path.GetFileName(active).Contains(".")?Path.GetFileName(active):Path.GetFileName(active)+".0"))active=directory;}
    if(s.Version.Major<42){active=root;common=null;}else if(active==null){active=common==null?root:Path.Combine(root,s.Version.Major+".0");}
    // Keep owned displaced-version metadata reachable until its suppression is restored.
    var retainedInfo=EffectiveSuppressions(s.Store.receipts).Where(r=>Same(r.sourceRoot,root)).SelectMany(r=>r.entries).Where(e=>e.kind=="metadata"&&OwnedInfo(root,e.target)).Select(e=>e.target).Concat(s.InfoBefore.Keys.Where(file=>OwnedInfo(root,file)));
    var infoFiles=new[]{Path.Combine(active,"mod.info"),Path.Combine(common??active,"mod.info"),Path.Combine(root,"mod.info")}.Concat(retainedInfo).Distinct(StringComparer.OrdinalIgnoreCase).ToArray();foreach(string file in infoFiles)Info(file,s,budget);var a=Info(Path.Combine(active,"mod.info"),s,budget);var c=common==null?new Dictionary<string,string>(StringComparer.OrdinalIgnoreCase):Info(Path.Combine(common,"mod.info"),s,budget);var metadata=new Dictionary<string,string>(c,StringComparer.OrdinalIgnoreCase);foreach(var pair in a)metadata[pair.Key]=pair.Value;
    string dependencyId=Value(metadata,"id");if(SaveProfiles.Id(dependencyId)){List<string> edges;if(!s.Dependencies.TryGetValue(dependencyId,out edges)){edges=new List<string>();s.Dependencies[dependencyId]=edges;}edges.AddRange(Value(metadata,"require").Split(new[]{',',';'},StringSplitOptions.RemoveEmptyEntries).Select(v=>Canonical(v.Trim())));}if(!infoFiles.Any(file=>s.InfoCache[Full(file)].Keys.Any(key=>System.Text.RegularExpressions.Regex.IsMatch(key,"^javaJarFile[0-9]*$",System.Text.RegularExpressions.RegexOptions.IgnoreCase)||key.Equals("javaPkgName",StringComparison.OrdinalIgnoreCase)||key.Equals("javaPreload",StringComparison.OrdinalIgnoreCase)))&&Managed(Value(metadata,"id"))=="")return;
    string id=Value(metadata,"id");if(!SaveProfiles.Id(id))throw new IOException("Java 模组缺少明确的有效 ID。");var row=new Row{modId=id,name=Value(metadata,"name")==""?id:Value(metadata,"name"),version=Value(metadata,"modversion"),workshopId=item??"",sourceKind=source,managedKey=Managed(id),packageName=Value(metadata,"javaPkgName"),requires=Value(metadata,"require").Split(new[]{',',';'},StringSplitOptions.RemoveEmptyEntries).Select(v=>Canonical(v.Trim())).Distinct().ToArray()};row.token=Hash(Utf8.GetBytes(Full(engine.Game).ToUpperInvariant()+"\n"+root.ToUpperInvariant()+"\n"+id));var candidate=new Candidate{Root=root,Row=row,Metadata=metadata,GameMetadata=metadata,InfoFiles=infoFiles,MetadataSafe=!infoFiles.Any(s.ProtectedInfo.Contains)};Receipt suppression;if(s.Suppressions.TryGetValue(root,out suppression)){candidate.Suppression=suppression;candidate.MetadataCurrent=suppression.entries.Where(e=>e.kind=="metadata").All(e=>s.InfoRaw.ContainsKey(Full(e.target))&&Hash(s.InfoRaw[Full(e.target)])==e.after);row.javaBlocked=!infoFiles.Any(file=>InfoText(s.InfoRaw[Full(file)]).Split(new[]{'\r','\n'}).Any(JavaLine));if(!candidate.MetadataCurrent){candidate.Safe=false;row.limitations=new[]{"屏蔽后的元数据已被其他程序修改，未开放恢复或启用。"};}}s.Candidates.Add(candidate);
    if(candidate.InfoFiles.Any(file=>s.AmbiguousInfo.Contains(Full(file))))throw new IOException("模组 ID、依赖或 Java 加载声明存在冲突，未开放修改。");if(Value(a,"id")!=""&&Value(c,"id")!=""&&Value(a,"id")!=Value(c,"id"))throw new IOException("common 与版本目录声明了不同模组 ID。");
    var payloads=new List<string>();var choices=new List<Tuple<Dictionary<string,string>,string>>{Tuple.Create(a,active)};if(common!=null){choices.Add(Tuple.Create(c,common));choices.Add(Tuple.Create(c,active));}
    string platformWarning=null;Version buddy;bool numbered=Version.TryParse(s.BuddyVersion,out buddy)&&buddy.Major>=3;
    foreach(var choice in choices){bool chosen=false,clientPath=false;var declarations=choice.Item1.Keys.Where(key=>System.Text.RegularExpressions.Regex.IsMatch(key,"^javaJarFile[0-9]*$",System.Text.RegularExpressions.RegexOptions.IgnoreCase)).Select(key=>new{Key=key,Suffix=key.Substring(11),Order=key.Substring(11).TrimStart('0')}).Where(value=>numbered||value.Suffix=="").OrderBy(value=>value.Order.Length).ThenBy(value=>value.Order,StringComparer.Ordinal).ThenBy(value=>value.Suffix.Length);
     foreach(var declaration in declarations){scanCancel.ThrowIfCancellationRequested();string relative=Value(choice.Item1,declaration.Key);if(relative=="")continue;string path;try{path=Payload(root,choice.Item2,relative);}catch(IOException ex){if(relative.Replace('\\','/').IndexOf("media/java/server/",StringComparison.OrdinalIgnoreCase)<0)throw;platformWarning=ex.Message;continue;}clientPath=true;payloads.Add(path);string pkg=Value(metadata,"javaPkgName");if(!System.Text.RegularExpressions.Regex.IsMatch(pkg,"^[A-Za-z_$][A-Za-z0-9_$]*(?:\\.[A-Za-z_$][A-Za-z0-9_$]*)*$"))throw new IOException("Java 包身份缺失或无法识别。");if(chosen)continue;
      try{Versions(s.BuddyVersion,choice.Item1,"ZBVersionMin"+declaration.Suffix,"ZBVersionMax"+declaration.Suffix,false);}catch(IOException){continue;}chosen=true;
      if(candidate.Selected==null&&File.Exists(path)){candidate.Selected=path;candidate.Metadata=new Dictionary<string,string>(choice.Item1,StringComparer.OrdinalIgnoreCase);candidate.Metadata["ZBVersionMin"]=Value(choice.Item1,"ZBVersionMin"+declaration.Suffix);candidate.Metadata["ZBVersionMax"]=Value(choice.Item1,"ZBVersionMax"+declaration.Suffix);row.packageName=pkg;row.name=Value(choice.Item1,"name")==""?row.name:Value(choice.Item1,"name");}
     }
     if(!clientPath&&platformWarning!=null)throw new IOException(platformWarning);
    }
    if(candidate.Selected==null&&platformWarning!=null)throw new IOException(platformWarning);

    candidate.Payloads=payloads.Distinct(StringComparer.OrdinalIgnoreCase).ToArray();if(candidate.Payloads.Length==0&&row.managedKey=="")throw new IOException("模组未声明可管理的 Java 文件。");foreach(string path in candidate.Payloads){var info=new FileInfo(path);s.Evidence.Add(path+"="+(info.Exists?info.Length+":"+info.LastWriteTimeUtc.Ticks:"absent"));}
