  Receipt FindReceipt(Snapshot s,Candidate c,string id){var r=s.Store.receipts.SingleOrDefault(v=>v.id==id&&v.token==c.Row.token&&!v.restored);if(r==null||!Opaque(r.id))throw new IOException("恢复记录不存在或已恢复。");ValidateReceipt(r,c,s);return r;}
