  string Transaction(Receipt r){return Path.Combine(folder,r.id);}
  string Backup(Receipt r,int index,bool after){return Path.Combine(Transaction(r),index+(after?".after":".before"));}
  static string Retired(Receipt r,Entry e){return Path.Combine(Path.GetDirectoryName(e.target),".ozl-java-"+r.id+"-"+e.index+".old");}
