    }catch(Exception ex){bool restored=!committed&&(active==null||Rollback(active));result.status=restored?(ex is OperationCanceledException?"cancelled":"failed"):"recoveryRequired";result.message=restored?(ex is OperationCanceledException?"已取消；本次修改已撤销。":ex.Message):"部分文件已有其他改动，未覆盖；请检查 Java 组件恢复状态。";}result.recoveryPending=File.Exists(pendingPath);return result;
   });}catch(Exception ex){result.message=ex.Message;result.recoveryPending=File.Exists(pendingPath);return result;}}}
  Receipt Pending(Snapshot s){byte[] bytes=Read(pendingPath);if(bytes==null)return null;var receipt=Json().Deserialize<Receipt>(Text(bytes));if(receipt==null)throw new IOException("未完成的组件记录无效。");var candidate=s.Candidates.SingleOrDefault(v=>v.Row.token==receipt.token);if(candidate==null||!candidate.MetadataSafe)throw new IOException("未完成组件的来源无法核实。");ValidateReceipt(receipt,candidate,s);return receipt;}
  string RecoveryStamp(Receipt r){return Hash(Utf8.GetBytes(Hash(Read(storePath))+"\n"+Hash(Read(pendingPath))+"\n"+string.Join("\n",r.entries.Select(e=>e.target+"="+HashFile(e.target)+":"+HashFile(Retired(r,e))))));}
  RecoveryResult RecoveryState(){var state=new RecoveryResult{pending=File.Exists(pendingPath),message="没有待恢复的 Java 组件操作。"};if(!state.pending)return state;state.message="存在未完成的 Java 组件操作；请核对私人备份。";try{var s=Scan();if(!s.StoreKnown)throw new IOException("组件恢复记录无法核实。");var r=Pending(s);bool committed=Committed(r,s.Store);foreach(var entry in r.entries.Where(e=>e.attempted)){string hash=HashFile(entry.target);if(committed&&hash!=entry.after)return state;if(hash!=entry.before&&hash!=entry.after&&!(hash=="absent"&&HashFile(Retired(r,entry))==entry.before))return state;}state.supported=true;state.stamp=RecoveryStamp(r);state.message="发现中断的 Java 组件操作；可恢复仍属于本次操作的修改。";}catch{}return state;}
  public object Recovery(){lock(gate){Ready();return RecoveryState();}}
  public object Recover(string stamp,bool confirmed,CancellationToken cancel){lock(gate){Ready();var result=new Result{status="cancelled",message="已取消，未开始恢复。",recoveryPending=File.Exists(pendingPath)};if(!confirmed||cancel.IsCancellationRequested)return result;try{return Locked<object>(()=>{Guard();var state=RecoveryState();if(!state.pending||!state.supported||state.stamp!=stamp)throw new IOException("恢复预览已变化，未覆盖文件。");var snapshot=Scan();var r=Pending(snapshot);cancel.ThrowIfCancellationRequested();bool recovered;if(Committed(r,snapshot.Store)){CleanRetired(r);File.Delete(pendingPath);recovered=true;}else recovered=Rollback(r);if(!recovered){result.status="recoveryRequired";result.message="部分目标已改变，已保留私人备份和恢复记录。";}else{result.status="recovered";result.changed=true;result.message="已恢复本次中断的 Java 组件修改。";}result.recoveryPending=File.Exists(pendingPath);return result;});}catch(Exception ex){result.status=ex is OperationCanceledException?"cancelled":"recoveryRequired";result.message=ex.Message;result.recoveryPending=File.Exists(pendingPath);return result;}}}
 }
